package com.library;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import java.sql.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

@EnabledIfEnvironmentVariable(named="MYSQL_TEST_URL",matches=".+")
public class CatalogPublicationMigrationTest {
    @Test void actualV13ToV14PreservesSixtyThreeOldTablesAndFrozenNonemptyMetadataAndIdentity()throws Exception{
        String base=System.getenv("MYSQL_TEST_URL"),user=System.getenv().getOrDefault("MYSQL_TEST_USER","root"),password=System.getenv("MYSQL_TEST_PASSWORD");if(base==null||!base.matches("jdbc:mysql://[^/]+/library_repair_tests(?:\\?.*)?"))throw new IllegalStateException("Disposable schema only");String schema="library_repair_tests_b36_"+UUID.randomUUID().toString().replace("-",""),url=base.replace("/library_repair_tests","/"+schema);
        try(Connection c=DriverManager.getConnection(base,user,password);Statement s=c.createStatement()){s.execute("CREATE DATABASE `"+schema+"` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");}
        try{Flyway.configure().dataSource(url,user,password).locations("classpath:db/migration").target("13").load().migrate();JdbcTemplate j=new JdbcTemplate(new DriverManagerDataSource(url,user,password));j.update("INSERT INTO book_category(id,name) VALUES (89001,'合成出版旧分类')");j.update("INSERT INTO publisher(id,name) VALUES (89001,'合成出版旧出版社')");j.update("INSERT INTO book(id,isbn,title,publisher,category_id,publish_date,pages,description,stock_total,stock_available,catalog_identity_revision) VALUES (89001,'B36-MIGRATION','合成原书名','合成原出版社',89001,'2024-02-29',0,?,1,1,7)","旧原文\n\t📚");j.update("INSERT INTO book_copy(id,book_id,barcode,action_version) VALUES (89001,89001,'000B36Aa ',9)");j.update("INSERT INTO catalog_book_attribute(book_id,revision,display_title_override,display_origin,updated_at) VALUES (89001,3,'合成原展示','MANUAL','2026-01-01')");j.update("INSERT INTO catalog_book_publisher(book_id,publisher_id,source_name,revision,updated_at) VALUES (89001,89001,'合成原文',2,'2026-01-01')");j.update("INSERT INTO catalog_book_theme(book_id,category_id,source_name,revision,updated_at) VALUES (89001,89001,'合成原主题',2,'2026-01-01')");j.update("INSERT INTO catalog_identity_request(id,operation_key,book_id,actor_id,mode,input_hash,request_json,preview_json,preview_digest,state,created_at,expires_at,receipt_json,committed_at) VALUES (89001,X'423336',89001,89001,'MANUAL',?,'{\"frozen\":null}','{\"zero\":0}',?,'COMMITTED','2026-01-01','2026-01-02','{\"empty\":\"\"}','2026-01-01')","a".repeat(64),"b".repeat(64));j.update("INSERT INTO catalog_identity_event(request_id,book_id,entity_kind,entity_id,before_revision,after_revision,changed_fields_json,before_json,after_json,actor_id,occurred_at,reason) VALUES (89001,89001,'BOOK_THEME',89001,1,2,'[\"themes\"]','{}','{\"frozen\":true}',89001,'2026-01-01','合成旧依据')");CatalogIdentityMigrationTest helpers=new CatalogIdentityMigrationTest();helpers.frozenV8(j);var columns=helpers.columns(url,user,password);assertEquals(63,columns.size());var before=helpers.values(url,user,password,columns);var definitions=helpers.definitions(url,user,password);var history=j.queryForList("SELECT * FROM flyway_schema_history ORDER BY installed_rank");Flyway migration=Flyway.configure().dataSource(url,user,password).locations("classpath:db/migration").target("14").load();assertEquals(1,migration.migrate().migrationsExecuted);assertEquals(0,migration.migrate().migrationsExecuted);var after=helpers.values(url,user,password,columns);after.put("flyway_schema_history",before.get("flyway_schema_history"));assertEquals(before,after);assertEquals(history,j.queryForList("SELECT * FROM flyway_schema_history WHERE version IS NULL OR version<>'14' ORDER BY installed_rank"));var newDefinitions=helpers.definitions(url,user,password);assertEquals(65,newDefinitions.size());for(var e:definitions.entrySet())if(!e.getKey().equals("book"))assertEquals(e.getValue(),newDefinitions.get(e.getKey()),e.getKey());assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM book WHERE publication_revision<>0",Integer.class));assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM catalog_publication_request",Integer.class));assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM catalog_publication_event",Integer.class));String dir=System.getProperty("b36.evidence.dir");if(dir!=null){java.nio.file.Files.writeString(java.nio.file.Path.of(dir,"actual-ddl.json"),com.library.catalogattributes.CatalogAttributeSupport.JSON.writerWithDefaultPrettyPrinter().writeValueAsString(Map.of("book",newDefinitions.get("book"),"catalog_publication_request",newDefinitions.get("catalog_publication_request"),"catalog_publication_event",newDefinitions.get("catalog_publication_event"))));}System.out.println("B36_MIGRATION oldTables=63 oldColumnsAndValues=preserved unchangedDefinitions=62 publicationRevisionZero=true newTables=2 empty=true V8V12V13Nonempty=preserved");
        }finally{try(Connection c=DriverManager.getConnection(base,user,password);Statement s=c.createStatement()){s.execute("DROP DATABASE `"+schema+"`");}}
    }
}
